/* Keep a pointer and a scalar argument live on both sides of calls.
 * The result stores, argument ordering and repeated conversions check
 * call liveness, not only the mathematical result of an isolated cast. */
static W unsigned_probe(const struct sample *p, W a, W b, W c)
{
    in.u = p->x;
    sf.f = (float)in.u;
    if (sf.word != p->sf) return 1;
    df.d = (double)in.u;
    if (df.word[0] != p->dh || df.word[1] != p->dl) return 2;
    if (p->inverse && (W)sf.f != p->back) return 3;
    if ((W)df.d != p->x) return 4;
    if (a+b+c != sentinel+3) return 5;
    return 0;
}
